import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (4,):
        raise ValueError("Input x must be a 1D NumPy array of shape (4,).")

    quadratic_term = np.sum(x**2) * 0.5
    interaction_term = 0.1 * x[0] * x[1]
    gaussian = np.exp(-0.5 * np.sum((x - 1)**2))

    result = 0.1 * quadratic_term + 0.1 * interaction_term - 0.1*gaussian + 0.3

    return float(result)
